
SET NOCOUNT ON;
BEGIN TRANSACTION;

DELETE FROM Alarms;


DECLARE @NowRomania datetime2 =
    CAST(SYSUTCDATETIME() AT TIME ZONE 'UTC' AT TIME ZONE 'GTB Standard Time' AS datetime2);

DECLARE @MaxFirst datetime2 =
    (SELECT MAX(FIRST_OCCURENCE_DATETIME) FROM Alarms);

DECLARE @ShiftSeconds int =
    DATEDIFF(SECOND, @MaxFirst, @NowRomania);

UPDATE Alarms
SET
    FIRST_OCCURENCE_DATETIME = DATEADD(SECOND, @ShiftSeconds, FIRST_OCCURENCE_DATETIME),
    LAST_OCCURENCE_DATETIME  = DATEADD(SECOND, @ShiftSeconds, LAST_OCCURENCE_DATETIME),
    CLEAR_OCCURENCE_DATETIME =
        CASE WHEN CLEAR_OCCURENCE_DATETIME IS NULL THEN NULL
             ELSE DATEADD(SECOND, @ShiftSeconds, CLEAR_OCCURENCE_DATETIME)
        END,
    DELETED_DATETIME =
        CASE WHEN DELETED_DATETIME IS NULL THEN NULL
             ELSE DATEADD(SECOND, @ShiftSeconds, DELETED_DATETIME)
        END;

COMMIT TRANSACTION;